spQuotationStateEliminar.definition:
CREATE OR REPLACE PROCEDURE public."spQuotationStateEliminar"(IN p_id integer, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
